"use client";

import { useState, useRef } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import {
  Plus, Edit3, Trash2, Eye, Calendar, X,
  UploadCloud, Image as ImageIcon, RefreshCw, Upload
} from "lucide-react";

type Props = {
  initialPosts: any[];
  createBerita: (formData: FormData) => Promise<any>;
  updateBerita: (formData: FormData) => Promise<any>;
  deleteBerita: (id: number) => Promise<any>;
};

export default function BeritaClient({
  initialPosts,
  createBerita,
  updateBerita,
  deleteBerita,
}: Props) {
  const [posts, setPosts] = useState(initialPosts);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingPost, setEditingPost] = useState<any | null>(null);

  const [previewImage, setPreviewImage] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const openEditor = (post?: any) => {
    setEditingPost(post || null);
    setPreviewImage(post?.gambar || "");
    setIsEditorOpen(true);
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Hapus berita ini permanen?")) return;
    await deleteBerita(id);
    setPosts((p) => p.filter((x) => x.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 4 * 1024 * 1024) {
      alert("Maksimal 4MB");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => setPreviewImage(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);

    const formData = new FormData(e.currentTarget);
    if (previewImage) formData.set("gambar", previewImage);

    try {
      let result;
      if (editingPost) {
        formData.set("id", editingPost.id);
        result = await updateBerita(formData);
      } else {
        result = await createBerita(formData);
      }

      if (!result?.success) {
        alert(result?.message || "Gagal menerbitkan berita");
        return;
      }

      alert("Berita berhasil disimpan");
      window.location.reload();
    } catch (err) {
      console.error(err);
      alert("Server error. Cek terminal.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <>
      <button onClick={() => openEditor()} className="btn-primary">
        <Plus /> Tulis Berita
      </button>

      <AnimatePresence>
        {isEditorOpen && (
          <motion.div className="fixed inset-0 z-50 bg-white">
            <form onSubmit={handleSubmit} className="h-full flex flex-col">
              <header className="flex justify-between p-4 border-b">
                <button type="button" onClick={() => setIsEditorOpen(false)}>
                  <X />
                </button>
                <button disabled={isSubmitting} type="submit">
                  {isSubmitting ? "Publishing..." : "Publish"}
                </button>
              </header>

              <main className="flex-1 p-10 space-y-6">
                <div className="h-64 border-dashed border-2 rounded-xl flex items-center justify-center">
                  {previewImage ? (
                    <Image src={previewImage} alt="" fill className="object-cover" />
                  ) : (
                    <button type="button" onClick={() => fileInputRef.current?.click()}>
                      <ImageIcon size={64} />
                    </button>
                  )}
                  <input
                    ref={fileInputRef}
                    type="file"
                    className="hidden"
                    accept="image/*"
                    onChange={handleImageUpload}
                  />
                  <input type="hidden" name="gambar" value={previewImage} />
                </div>

                <input name="judul" defaultValue={editingPost?.judul} required />
                <select name="kategori" defaultValue={editingPost?.kategori || "Umum"}>
                  <option>Umum</option>
                  <option>Event</option>
                  <option>Prestasi</option>
                </select>
                <textarea
                  name="konten"
                  defaultValue={editingPost?.konten}
                  required
                  rows={10}
                />
              </main>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
